<script setup>
import {artifactCodePresentation} from '../artifactPresentation.js'
import {buildRunLabel,artifactBuildLabel,releaseOrderLabel} from '../buildNumber.js'
import ArtifactDownloadButton from './ArtifactDownloadButton.vue'
import {useTableLayout} from '../../shared/composables/tableLayout.js'
const {pinTableActions}=useTableLayout()


import {ref, watch, onBeforeUnmount, nextTick, computed} from 'vue'
import {useRoute, useRouter} from 'vue-router'



import GitBranchSelect from './GitBranchSelect.vue'
import DateRangeFilter from '../../shared/components/DateRangeFilter.vue'
import Stages from '../../shared/components/Stages.vue'
import {buildState, buildScroll} from '../buildNavigation.js'
import {activeReleaseStatuses} from '../releasePolling.js'
import {buildVariantLabel} from '../buildVariant.js'
const props=defineProps({service:String,kind:{type:String,default:'runs'},environments:{type:Array,default:()=>[]},me:{type:Object,default:()=>({})}})
const emit=defineEmits(['open','publish','action'])
const route=useRoute(),router=useRouter()
const filters=buildState(props.service+':'+props.kind,{q:'',status:'',branch:'',actor:'',environment:'',start:'',end:'',page:1,page_size:20},()=>props.me.username)
const page=ref({items:[],total:0,page:1,page_size:20}),loading=ref(false),error=ref(''),peek=ref(null)
const focusedRelease=ref(null),publishing=ref(0)
const rows=computed(()=>focusedRelease.value?[focusedRelease.value,...page.value.items.filter(r=>r.id!==focusedRelease.value.id)]:page.value.items)
const scroll=buildScroll(props.service+':'+props.kind)
const now=ref(Date.now()),clock=setInterval(()=>now.value=Date.now(),1000)
const canManage=r=>r.actor===props.me.username||props.me.role==='admin'||props.me.username==='local'
let seq=0,timer,debounce,initial=true
const endpoint=computed(()=>({runs:'pipeline/runs',artifacts:'artifacts',releases:'release-orders'}[props.kind]))
const statuses=[{value:'needs_review',label:'待核对'},{value:'waiting_manual',label:'待手动发布'},{value:'success',label:'成功'},{value:'failed',label:'失败'},{value:'running',label:'运行中'},{value:'canceled',label:'已取消'},{value:'interrupted',label:'已中断'},{value:'pending_approval',label:'待审批'},{value:'waiting_next_batch',label:'批次暂停'},{value:'waiting_deploy',label:'待部署'}]
const status=value=>({needs_review:'待核对',timed_out:'超时待核对',rejected:'已拒绝','rolled-back':'已回滚','rollback-failed':'回滚失败',rolling_back:'回滚中',queued:'排队中'}[value]||statuses.find(s=>s.value===value)?.label||value)
const date=value=>value?new Date(value*1000).toLocaleString('zh-CN',{hour12:false}):'—'
const duration=r=>r.ended_at?Math.max(0,r.ended_at-r.started_at)+'s':'运行中'
const stage=r=>r.stages?.find(s=>['failed','running','waiting'].includes(s.status))?.name||((r.stages||[]).filter(s=>s.status==='success').length+' / '+(r.stages||[]).length)
const canApprove=r=>r.actor!==props.me.username&&String(r.target_snapshot?.approvers||props.environments.find(e=>e.environment===r.environment)?.approvers||'').split(/[,;\s]+/).includes(props.me.username)
const pages=computed(()=>Math.max(1,Math.ceil(page.value.total/filters.value.page_size)))
async function load(quiet=false){const request=++seq;clearTimeout(timer);if(!quiet)loading.value=true;error.value=''
 try{const q=new URLSearchParams({service:props.service});for(const [k,v] of Object.entries(filters.value))if(v!==''&&v!=null)q.set(k,['start','end'].includes(k)?String(Math.floor(new Date(v).getTime()/1000)):String(v))
  const r=await fetch('api/'+endpoint.value+'/page?'+q),v=await r.json();if(!r.ok)throw Error(v.error||'记录读取失败');if(!Array.isArray(v.items)||!Number.isInteger(v.total))throw Error('分页响应无效，请重试');if(request!==seq)return;page.value=v
  if(initial){initial=false;await scroll.restore()}
  if(props.kind==='releases'&&route.query.release){const id=Number(route.query.release);if(Number.isSafeInteger(id)&&id>0){const response=await fetch('api/releases/'+id);const item=await response.json();if(request!==seq)return;if(!response.ok)throw Error(item.error||'发布单读取失败');if(item.service!==props.service)throw Error('发布单不属于当前应用');focusedRelease.value=item}}
  if(rows.value.some(r=>(props.kind==='releases'?activeReleaseStatuses:['running','queued','waiting_deploy']).includes(r.status)))timer=setTimeout(()=>load(true),3000)
 }catch(e){if(request===seq){error.value=e.message;timer=setTimeout(()=>load(true),3000)}}finally{if(request===seq)loading.value=false}
}
function reset(){filters.value.page=1}
watch(filters,()=>{seq++;loading.value=true;clearTimeout(timer);clearTimeout(debounce);debounce=setTimeout(load,200)},{deep:true})
watch(()=>props.service,()=>load(),{immediate:true})
watch(()=>route.query.release,()=>{focusedRelease.value=null;load()})
onBeforeUnmount(()=>{seq++;clearTimeout(timer);clearTimeout(debounce);clearInterval(clock)})
function open(r){if(loading.value)return;scroll.remember();if(props.kind==='runs')router.push({path:'/run/'+r.id,query:{return:route.fullPath}});else if(props.kind==='artifacts')peek.value=r;else emit('open',r)}
async function publish(a){
 if(loading.value||publishing.value)return
 scroll.remember()
 if(props.kind!=='runs'){emit('publish',a);return}
 publishing.value=a.id
 try{const response=await fetch('api/artifacts/'+encodeURIComponent(a.id));const artifact=await response.json();if(!response.ok||Number(artifact.id)!==Number(a.id)||artifact.service!==props.service)throw Error(artifact.error||'制品不属于当前应用或已不可用');emit('publish',artifact)}catch(e){error.value=e.message}finally{publishing.value=0}
}
function source(r){if(loading.value)return;scroll.remember();router.push({path:'/run/'+r.source_id,query:{return:route.fullPath}})}
function action(r,a){if(loading.value)return;emit('action',r,a)}
defineExpose({refresh:()=>load(true)})

import OptionPicker from '../../shared/components/OptionPicker.vue'



import {Badge,Button,DropdownMenu,DropdownMenuContent,DropdownMenuItem,DropdownMenuTrigger,Empty,EmptyContent,EmptyDescription,EmptyHeader,Input,Pagination,PaginationContent,PaginationNext,PaginationPrevious,Popover,PopoverContent,PopoverTrigger,Sheet,SheetContent,SheetDescription,SheetFooter,SheetHeader,SheetTitle,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><section class="build-records min-w-0 space-y-4"><header class="flex min-w-0 flex-wrap items-center gap-2"><h3 class="text-base font-semibold">{{kind==='runs'?'构建记录':kind==='artifacts'?'制品库':'发布记录'}}</h3><slot name="heading-extra"/><span class="text-sm tabular-nums text-muted-foreground">{{page.total}}</span><span v-if="loading" class="text-xs text-muted-foreground" role="status">正在读取…</span><div v-if="$slots.actions" class="ml-auto flex shrink-0 items-center gap-2"><slot name="actions"/></div></header><div v-if="$slots.context" class="min-w-0 text-sm text-muted-foreground"><slot name="context"/></div><div class="record-filters"><InputGroup  class="min-w-0 record-search"><InputGroupInput v-model="filters.q" :placeholder="kind==='artifacts'?'搜索代码版本或摘要':'搜索代码版本、分支或人员'" @input="reset"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="filters.q" :disabled="false" size="icon-xs" aria-label="清空输入" @click="filters.q='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-if="kind!=='artifacts'" v-model="filters.status" :options="statuses" :style="{width:'120px',maxWidth:'100%'}" all-label="全部状态" @change="reset"/><GitBranchSelect v-if="kind==='runs'" v-model="filters.branch" compact :repositories="[{service}]" placeholder="全部分支（可搜索或输入）" @update:model-value="reset" class="record-branch"/><InputGroup v-if="kind!=='artifacts'"  class="min-w-0 narrow"><InputGroupInput  v-model="filters.actor" placeholder="发起人" @input="reset"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="filters.actor" :disabled="false" size="icon-xs" aria-label="清空输入" @click="filters.actor='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-if="kind==='releases'" v-model="filters.environment" :options="environments.map(e=>({value:e.environment||e.name,label:e.display_name||e.name}))" all-label="全部环境" @change="reset"/><DateRangeFilter v-model:start="filters.start" v-model:end="filters.end" label="时间" width="280px" @change="reset"/></div><p v-if="error" role="alert" class="record-error">{{error}} <Button @click="load()" variant="outline" size="sm" type="button">重试</Button></p><p v-if="focusedRelease" class="focused-release-hint">已定位发布单 {{releaseOrderLabel(focusedRelease)}}；首行固定展示该交付，不受下面历史列表筛选影响。</p><div :aria-busy="loading" class="record-scroll"><div class="console-table min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:kind==='runs'?1220:kind==='artifacts'?1300:1080}).y?({x:kind==='runs'?1220:kind==='artifacts'?1300:1080}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)] [&_thead]:bg-muted [&_tbody_td]:py-3" :style="{'--table-min-width':(({x:kind==='runs'?1220:kind==='artifacts'?1300:1080}).x||({x:kind==='runs'?1220:kind==='artifacts'?1300:1080}).minWidth||1920)+'px'}"><TableHeader class="bg-muted"><TableRow><TableHead :style="{width:(210)+'px'}">编号 / 代码版本</TableHead><TableHead v-if="kind==='runs'" :style="{width:(200)+'px'}">分支 / 阶段</TableHead><TableHead v-if="kind==='artifacts'" :style="{width:(200)+'px'}">来源构建</TableHead><TableHead v-if="kind==='artifacts'" :style="{width:(160)+'px'}">目标分支 / 构建提交</TableHead><TableHead v-if="kind==='artifacts'" :style="{width:(180)+'px'}">曾发布环境</TableHead><TableHead v-if="kind==='releases'" :style="{width:(160)+'px'}">环境 / 批次</TableHead><TableHead :style="{width:(130)+'px'}">{{kind==='artifacts'?'类型':'状态'}}</TableHead><TableHead v-if="kind!=='artifacts'" :style="{width:(160)+'px'}">发起人{{kind==='releases'?' / 审批人':''}}</TableHead><TableHead v-if="kind==='runs'" :style="{width:(100)+'px'}">耗时</TableHead><TableHead :style="{width:(180)+'px'}">时间</TableHead><TableHead :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-muted':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-muted':''" :style="{width:(240)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (rows||[])" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow :class="(r=>r.id===focusedRelease?.id?'focused-release':'')(record)"><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><div><Button @click="open(r)" variant="ghost" size="sm" type="button">{{kind==='runs'?buildRunLabel(r):kind==='releases'?releaseOrderLabel(r):'#'+r.id}} · {{r.version||'待解析 Commit'}}</Button><small v-if="kind==='runs'&&r.artifact_id">制品 #{{r.artifact_id}}</small></div></template></div></TableCell><TableCell v-if="kind==='runs'" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><div><span>{{r.branch||'仓库默认分支'}}</span><small><Popover><PopoverTrigger as-child><Button :aria-label="'查看运行 '+r.id+' 阶段'" variant="ghost" size="sm" type="button">{{stage(r)}}</Button></PopoverTrigger><PopoverContent class="max-h-[80dvh] max-w-[calc(100vw-2rem)] overflow-auto" align="end" :style="{width:(400)+'px',maxWidth:'calc(100vw - 32px)'}"><Stages :stages="r.stages||[]"/></PopoverContent></Popover></small></div></template></div></TableCell><TableCell v-if="kind==='artifacts'" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><div><Button v-if="r.source==='pipeline-run'" @click="source(r)" variant="ghost" size="sm" type="button" :disabled="(loading)">构建 {{artifactBuildLabel(r)}}</Button><span v-else>{{r.source||'历史制品'}} #{{r.source_id}}</span><small>方案：{{buildVariantLabel(r)}}</small></div></template></div></TableCell><TableCell v-if="kind==='artifacts'" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><div class="whitespace-normal break-words" :title="artifactCodePresentation(r).branch">{{artifactCodePresentation(r).branch}}</div><small v-if="artifactCodePresentation(r).commit" class="block font-mono text-muted-foreground" :title="artifactCodePresentation(r).commit">{{artifactCodePresentation(r).commit.slice(0,12)}}</small></template></div></TableCell><TableCell v-if="kind==='artifacts'" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><div>{{r.published_environments?.length?r.published_environments.join(' / '):'尚无成功发布记录'}}</div></template></div></TableCell><TableCell v-if="kind==='releases'" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><div>{{r.environment}}<small v-if="r.manual_publication">手动发布 · {{r.manual_publication.assignee}}</small><small v-else>{{r.succeeded}} 成功 / {{r.failed}} 失败 / {{r.total}} 台</small></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><Badge :variant="(r.status==='success'?'green':r.status==='failed'?'red':r.status==='running'?'blue':'gray')==='red'?'destructive':'secondary'">{{kind==='artifacts'?r.kind:status(r.status)}}</Badge></template></div></TableCell><TableCell v-if="kind!=='artifacts'" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><div>{{r.actor||'local'}}<small v-if="r.approver">{{r.approver}}</small></div></template></div></TableCell><TableCell v-if="kind==='runs'" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><div>{{duration(r)}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:r} in [{record,rowIndex}]"><div>{{date(r.created_at||r.started_at)}}</div></template></div></TableCell><TableCell class="align-top" :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:r} in [{record,rowIndex}]"><div class="cell-actions"><Button @click="open(r)" variant="ghost" size="sm" type="button">详情</Button><Button v-if="kind==='runs'&&r.status==='success'&&r.artifact_id" :disabled="loading||!!publishing" @click="publish({id:r.artifact_id,service:r.service||service})" variant="ghost" size="sm" type="button">发布此制品</Button><ArtifactDownloadButton v-if="kind==='artifacts'" :artifact="r"/><Button v-if="kind==='artifacts'" @click="publish(r)" variant="ghost" size="sm" type="button">发布此制品</Button><DropdownMenu v-if="kind==='releases'&amp;&amp;((r.status==='pending_approval'&amp;&amp;canApprove(r))||(['success','waiting_next_batch','failed','canceled','pending_approval','queued'].includes(r.status)&amp;&amp;canManage(r)&amp;&amp;!r.recovery)||(r.status==='waiting_next_batch'&amp;&amp;canManage(r)))"><DropdownMenuTrigger as-child><Button variant="ghost" size="sm" type="button" :disabled="(loading)">更多</Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem v-if="r.status==='pending_approval'&&canApprove(r)" @select="action(r,'approve')">批准</DropdownMenuItem><DropdownMenuItem v-if="r.status==='pending_approval'&&canApprove(r)" @select="action(r,'reject')">拒绝</DropdownMenuItem><DropdownMenuItem v-if="['pending_approval','queued','waiting_next_batch'].includes(r.status)&&canManage(r)&&!r.recovery" @select="action(r,'cancel')">取消</DropdownMenuItem><DropdownMenuItem v-if="r.status==='waiting_next_batch'&&canManage(r)" @select="action(r,'continue')" :disabled="r.continue_after*1000>now">{{r.continue_after*1000>now?'观察中（'+Math.ceil((r.continue_after*1000-now)/1000)+'s）':r.recovery?'继续回退批次':'继续下一批'}}</DropdownMenuItem><DropdownMenuItem v-if="['success','waiting_next_batch','failed','canceled'].includes(r.status)&&canManage(r)&&!r.recovery" @select="action(r,'rollback')">回退</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></template></div></TableCell></TableRow></template><TableRow v-if="!(rows||[]).length"><TableCell :colspan="11"><Empty><EmptyHeader><EmptyDescription>{{error?'暂时无法读取记录':'没有匹配记录，可调整筛选条件'}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div><footer><div class="flex flex-wrap items-center justify-end gap-3 py-4"><span class="mr-auto text-sm text-muted-foreground">共 {{page.total}} 项</span><OptionPicker class="w-28" :model-value="filters.page_size" :options="([20,50,100]).map(value=>({value:Number(value),label:value+' 条/页'}))" @update:model-value="filters.page_size=$event;reset($event)"/><Pagination class="mx-0 w-auto" :disabled="loading" :page="filters.page" :total="page.total" :items-per-page="filters.page_size" @update:page="filters.page=$event;"><PaginationContent><PaginationPrevious /><span class="px-2 text-sm">{{filters.page}} / {{Math.max(1,Math.ceil((page.total)/(filters.page_size)))}}</span><PaginationNext /></PaginationContent></Pagination></div></footer><Sheet :open="!!peek" @update:open="async v=>{if(!v){peek=null}}"><SheetContent class="data-[side=right]:w-full gap-0 overflow-hidden p-0 data-[side=right]:sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (560)==='number'?(560)+'px':(560)}" :show-close-button="true" @interact-outside="e=>{e.preventDefault()}"><SheetHeader class="shrink-0 border-b p-5 pr-12"><SheetTitle>制品详情</SheetTitle><SheetDescription class="sr-only">详情与操作</SheetDescription></SheetHeader><div class="min-h-0 flex-1 overflow-auto p-5"><template v-if="peek"><h3>制品 #{{peek.id}} · {{peek.version}}</h3><dl class="my-4 grid gap-3"><div><dt class="text-sm text-muted-foreground">目标分支</dt><dd class="break-all">{{artifactCodePresentation(peek).branch}}</dd></div><div v-if="artifactCodePresentation(peek).sources.length"><dt class="text-sm text-muted-foreground">来源分支</dt><dd class="break-all">{{artifactCodePresentation(peek).sources.join("、")}}</dd></div><div><dt class="text-sm text-muted-foreground">构建提交 / 版本</dt><dd class="break-all font-mono">{{artifactCodePresentation(peek).commit||peek.version}}</dd></div><div v-if="artifactCodePresentation(peek).prepared"><dt class="text-sm text-muted-foreground">代码来源</dt><dd>按 {{artifactCodePresentation(peek).environment}} 环境的冻结代码准备结果构建</dd></div></dl><p>类型：{{peek.kind}} · 大小：{{peek.size||0}} 字节</p><p>摘要</p><code>{{peek.digest}}</code><p>存储位置</p><code>{{peek.uri}}</code><ArtifactDownloadButton :artifact="peek"/></template></div><SheetFooter v-if="peek"><Button @click="publish(peek)" variant="default" size="default" type="button">发布此制品</Button></SheetFooter></SheetContent></Sheet></section></template>
<style scoped>.build-records .record-filters>.record-search{flex:1 1 240px;max-width:360px}.build-records .record-filters>.record-branch{flex:1 1 200px;min-width:180px;max-width:260px}.build-records .record-filters>.narrow{flex:0 1 120px;min-width:100px;max-width:140px}.record-filters>[role=status]{font-size:.75rem;color:var(--muted-foreground)}
@media(max-width:650px){.build-records .record-filters>.record-search,.build-records .record-filters>.record-branch{flex-basis:100%;max-width:none;min-width:0}.record-filters>.compact-date-filter{width:100%!important}.build-records .record-filters>.narrow{flex:1;max-width:none}}
.focused-release{background:var(--brand-soft)}.focused-release-hint{font-size:.75rem;color:var(--muted-foreground);margin:4px 0 10px}
.record-filters{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.record-filters>.narrow{max-width:155px}.record-scroll{overflow:auto}.record-actions{white-space:nowrap}footer{min-width:0;border-top:1px solid var(--border);font-size:.75rem}footer>span:first-child{margin-right:auto}.record-empty{text-align:center;padding:36px;color:var(--muted-foreground)}.record-error,.record-status.failed{color:var(--error)}.record-status.success{color:var(--ok)}.record-status.running{color:var(--brand)}</style>
